(function () {
  "use strict";

  var THEME_KEY = "calculator-theme";
  var calc = Calculator();
  var display = document.getElementById("display");
  var keys = document.getElementById("keys");
  var themeToggle = document.getElementById("theme-toggle");
  var root = document.documentElement;

  function render() {
    display.textContent = calc.getDisplay();
  }

  function updateThemeControl() {
    var dark = root.dataset.theme === "dark";
    themeToggle.textContent = dark ? "Light theme" : "Dark theme";
    themeToggle.setAttribute("aria-label", dark ? "Switch to light theme" : "Switch to dark theme");
    themeToggle.setAttribute("aria-pressed", dark ? "true" : "false");
  }

  try {
    var saved = localStorage.getItem(THEME_KEY);
    if (saved === "light" || saved === "dark") {
      root.dataset.theme = saved;
    }
  } catch (e) {
    // storage unavailable: keep the default theme
  }

  updateThemeControl();
  render();

  themeToggle.addEventListener("click", function () {
    var next = root.dataset.theme === "dark" ? "light" : "dark";
    root.dataset.theme = next;
    try {
      localStorage.setItem(THEME_KEY, next);
    } catch (e) {
      // storage unavailable: theme applies for this visit only
    }
    updateThemeControl();
  });

  keys.addEventListener("click", function (event) {
    var button = event.target.closest("button");
    if (!button || !keys.contains(button)) {
      return;
    }
    var data = button.dataset;
    if (data.digit !== undefined) {
      calc.inputDigit(data.digit);
    } else if (data.operator !== undefined) {
      calc.chooseOperator(data.operator);
    } else if (data.action === "decimal") {
      calc.inputDecimal();
    } else if (data.action === "equals") {
      calc.equals();
    } else if (data.action === "clear") {
      calc.clear();
    } else if (data.action === "backspace") {
      calc.backspace();
    } else {
      return;
    }
    render();
  });

  document.addEventListener("keydown", function (event) {
    if (event.ctrlKey || event.metaKey || event.altKey) {
      return;
    }
    var key = event.key;
    if (typeof key !== "string") {
      return;
    }
    if (key.length === 1 && key >= "0" && key <= "9") {
      calc.inputDigit(key);
    } else if (key === ".") {
      calc.inputDecimal();
    } else if (key === "+" || key === "-" || key === "*" || key === "/") {
      calc.chooseOperator(key);
    } else if (key === "Enter") {
      calc.equals();
    } else if (key === "Backspace") {
      calc.backspace();
    } else if (key === "Escape") {
      calc.clear();
    } else {
      return;
    }
    event.preventDefault();
    render();
  });
})();

