(function (root) {
  "use strict";

  function format(n) {
    if (!isFinite(n)) {
      return null;
    }
    return String(parseFloat(n.toPrecision(12)));
  }

  function Calculator() {
    var entry = "0";
    var stored = null;
    var pending = null;
    var fresh = false;
    var error = false;

    function fail() {
      entry = "Error";
      error = true;
      stored = null;
      pending = null;
      fresh = true;
    }

    function apply(a, op, b) {
      if (op === "/" && b === 0) {
        return null;
      }
      var r;
      if (op === "+") {
        r = a + b;
      } else if (op === "-") {
        r = a - b;
      } else if (op === "*") {
        r = a * b;
      } else {
        r = a / b;
      }
      return format(r);
    }

    return {
      inputDigit: function (d) {
        d = String(d);
        if (!/^[0-9]$/.test(d)) {
          return;
        }
        if (fresh || error) {
          entry = d;
          fresh = false;
          error = false;
        } else if (entry === "0") {
          entry = d;
        } else {
          entry += d;
        }
      },

      inputDecimal: function () {
        if (fresh || error) {
          entry = "0.";
          fresh = false;
          error = false;
        } else if (entry.indexOf(".") === -1) {
          entry += ".";
        }
      },

      chooseOperator: function (op) {
        if (op !== "+" && op !== "-" && op !== "*" && op !== "/") {
          return;
        }
        if (error) {
          return;
        }
        if (pending !== null && fresh) {
          pending = op;
          return;
        }
        if (pending !== null) {
          var result = apply(stored, pending, parseFloat(entry));
          if (result === null) {
            fail();
            return;
          }
          entry = result;
        }
        stored = parseFloat(entry);
        pending = op;
        fresh = true;
      },

      equals: function () {
        if (error || pending === null) {
          return;
        }
        var result = apply(stored, pending, parseFloat(entry));
        if (result === null) {
          fail();
          return;
        }
        entry = result;
        stored = null;
        pending = null;
        fresh = true;
      },

      clear: function () {
        entry = "0";
        stored = null;
        pending = null;
        fresh = false;
        error = false;
      },

      backspace: function () {
        if (fresh || error) {
          return;
        }
        entry = entry.slice(0, -1);
        if (entry === "" || entry === "-") {
          entry = "0";
        }
      },

      getDisplay: function () {
        return entry;
      }
    };
  }

  root.Calculator = Calculator;
  if (typeof module !== "undefined" && module.exports) {
    module.exports = Calculator;
  }
})(typeof window !== "undefined" ? window : globalThis);

