:root,
html[data-theme="light"] {
  --page-bg: #f2f4f8;
  --text: #1a1f2b;
  --display-bg: #ffffff;
  --display-text: #1a1f2b;
  --digit-bg: #e2e6ee;
  --digit-hover: #c9d0de;
  --operator-bg: #cfe0ff;
  --operator-hover: #a9c6fb;
  --equals-bg: #2f6fed;
  --equals-hover: #1c55c4;
  --equals-text: #ffffff;
  --clear-bg: #ffd9d6;
  --clear-hover: #f9b4ae;
  --theme-bg: #ffffff;
  --theme-hover: #dde3ef;
  --focus-ring: #7a2be2;
}

html[data-theme="dark"] {
  --page-bg: #12151c;
  --text: #f1f3f8;
  --display-bg: #1f2430;
  --display-text: #f1f3f8;
  --digit-bg: #2c3342;
  --digit-hover: #424b60;
  --operator-bg: #35466b;
  --operator-hover: #4a6093;
  --equals-bg: #3b82f6;
  --equals-hover: #5b9bff;
  --equals-text: #ffffff;
  --clear-bg: #6b2f2b;
  --clear-hover: #8a3f3a;
  --theme-bg: #1f2430;
  --theme-hover: #333b4d;
  --focus-ring: #ffd23f;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background-color: var(--page-bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

.calculator {
  width: 100%;
  max-width: 360px;
  margin: 0 auto;
  padding: 16px 12px;
}

#display {
  margin: 12px 0;
  padding: 16px 12px;
  min-height: 64px;
  background-color: var(--display-bg);
  color: var(--display-text);
  font-size: 2rem;
  text-align: right;
  overflow-wrap: anywhere;
  border-radius: 8px;
}

#keys {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

button {
  min-height: 44px;
  min-width: 0;
  border: 1px solid transparent;
  border-radius: 8px;
  font: inherit;
  font-size: 1.25rem;
  color: var(--text);
  cursor: pointer;
  outline: none;
  box-shadow: none;
}

#theme-toggle {
  max-width: 100%;
  font-size: 1rem;
  padding: 0 12px;
  background-color: var(--theme-bg);
  border-color: var(--text);
}

.btn.digit {
  background-color: var(--digit-bg);
}

.btn.operator {
  background-color: var(--operator-bg);
}

.btn.equals {
  background-color: var(--equals-bg);
  color: var(--equals-text);
}

.btn.clear,
.btn.backspace {
  background-color: var(--clear-bg);
}

.btn.digit:hover {
  background-color: var(--digit-hover);
}

.btn.operator:hover {
  background-color: var(--operator-hover);
}

.btn.equals:hover {
  background-color: var(--equals-hover);
}

.btn.clear:hover,
.btn.backspace:hover {
  background-color: var(--clear-hover);
}

#theme-toggle:hover {
  background-color: var(--theme-hover);
}

button:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
  box-shadow: 0 0 0 5px var(--focus-ring);
}

